// Unicode dimension prober: prints ESCAPED input -> ESCAPED output, one per line.
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
const inputs = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const CONC = Number(process.argv[3] || 16);
function esc(s) {
  if (s === undefined || s === null) return String(s);
  let o = '';
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (ch === '\n') o += '\\n';
    else if (ch === '\r') o += '\\r';
    else if (ch === '\t') o += '\\t';
    else if (ch === '\\') o += '\\\\';
    else if (c < 0x20 || c === 0x7f) o += '\\x' + c.toString(16).padStart(2, '0');
    else if (c < 0x7f) o += ch;
    else o += '\\u{' + c.toString(16) + '}';
  }
  return o;
}
const results = new Array(inputs.length);
let idx = 0;
function next(done) {
  if (idx >= inputs.length) return done();
  const i = idx++;
  execFile(EXE, ['--a', inputs[i]], { maxBuffer: 1 << 26, encoding: 'utf8' }, (err, so, se) => {
    results[i] = { i, in: inputs[i], out: so, err: se, rc: err ? (err.code ?? 1) : 0 };
    next(done);
  });
}
let fin = 0;
const finish = () => {
  if (++fin !== CONC) return;
  for (const r of results) {
    let line = `[${String(r.i).padStart(3)}] ${JSON.stringify(esc(r.in))}  ->  ${JSON.stringify(esc(r.out))}`;
    if (r.rc !== 0) line += `   rc=${r.rc} err=${JSON.stringify((r.err || '').slice(-200))}`;
    console.log(line);
  }
};
for (let k = 0; k < CONC; k++) next(finish);

